package com.lmspilot.identity.domain; import java.time.Instant; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; public interface IdentitySystemLockRepository extends JpaRepository<IdentitySystemLockEntity,String> { @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select l from IdentitySystemLockEntity l where l.lockName=:lockName") Optional<IdentitySystemLockEntity> lock(@Param("lockName") String lockName); }
